"""Publish the companion map and chapter graph from the SAME placements used in UE."""
import json,sys,math,html
from pathlib import Path
import Penance_Town_V5_Design as p
root=Path(__file__).resolve().parents[1]/'Docs/V5';root.mkdir(exist_ok=True)
p.export(root/'Penance_V5_Implementation.json');data=json.loads((root/'Penance_V5_Implementation.json').read_text())
t=p.Terrain();data['heights']=[[round(t.surface(x,y),1) for x in range(0,481,8)] for y in range(0,441,8)]
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Penance · V5 World Atlas</title><style>
*{box-sizing:border-box}body{margin:0;background:#101b1b;color:#e4e8df;font:14px system-ui,sans-serif}header{padding:25px 32px;border-bottom:1px solid #435850}h1{font-size:28px;margin:5px 0}small,.muted{color:#a7bcb1}main{display:grid;grid-template-columns:minmax(550px,1fr) 340px;gap:18px;padding:20px}section,aside{border:1px solid #435850;border-radius:12px;background:#172725;overflow:hidden}.tools{padding:12px;display:flex;flex-wrap:wrap;gap:12px;border-bottom:1px solid #435850}button,select{background:#2d4540;color:#eee;border:1px solid #65796b;border-radius:5px;padding:6px}canvas{display:block;width:100%;height:calc(100vh - 205px);min-height:580px;touch-action:none;cursor:grab}aside{padding:20px;height:calc(100vh - 150px);overflow:auto}h2{font-size:19px;color:#e2c68d}p{line-height:1.6}li{margin:8px 0}#coords{padding:8px 16px;color:#a7bcb1}dt{color:#a7bcb1;margin-top:12px}dd{margin:4px 0}.badge{padding:5px 8px;border:1px solid #8c9c79;border-radius:20px;font-size:11px}.note{padding:15px 32px;color:#c8cfbd}@media(max-width:950px){main{grid-template-columns:1fr}aside{height:auto}canvas{height:650px}}</style>
<header><small>PENANCE / ENVIRONMENT BLOCKOUT / V5</small><h1>The crossing that built the town</h1><small>480 × 440 m · north ↑ · 1 m = 100 Unreal Units · saved 3D layout companion</small> <span class="badge">BLOCKOUT + CONDENSED OPENING PREVIEW</span></header>
<main><section><div class="tools"><button id="fit">Fit town</button><button id="plus">＋</button><button id="minus">−</button><label><input type="checkbox" id="terrain" checked>Terrain</label><label><input type="checkbox" id="labels" checked>Labels</label><label><input type="checkbox" id="routes" checked>Paths</label><label><input type="checkbox" id="sight">Sightlines</label><label><input type="checkbox" id="slice" checked>Opening slice</label><select id="chapter"><option value="">14 chapters</option></select></div><canvas id="map"></canvas><div id="coords">Wheel to zoom · drag to pan · click buildings or select a chapter</div></section><aside id="details"><h2>A real place before the horror</h2><p>The mill crossing predates the civic street. Orchard cottages grew west of it; postwar homes climbed Briar Rise. Church land and the Foster estate share the older ridge road.</p><p>Six months after the Quieting, the town is intact. Interrupted routines and a few working lights make the absence conspicuous.</p><h2>Readable geography</h2><p>The curved creek separates everyday town life from the church and estate. One public bridge is the dependable crossing. A closed older footbridge reserves a later shortcut.</p><h2>What is playable</h2><p>Arrival → lit House01 → changed exit → Orchard Loop → park → bridge → church → basement escape → Foster approach. This condensed preview does not implement fourteen finished chapters.</p><p>Open <b>/Game/Maps/V5/Penance_Town_V5</b> in Unreal 5.7.4 and press Play.</p></aside></main><div class="note">Existing player, original maps and House01 interior preserved. Road widths: 7 m public spine, 5.6–5.8 m residential, 4 m service. Later encounters, interior production and unrestricted enemy AI remain planned.</div>
<script>const D=__DATA__;
const cv=document.getElementById('map'),ctx=cv.getContext('2d'),side=document.getElementById('details');let S=1,ox=0,oy=0,drag=null,moved=false;
const colors={Residential:'#b5ad98',Commerce:'#c49e72',Civic:'#87b0ad',Estate:'#b6a4c3',Utility:'#93a4ac',Stone:'#a2ac98'};
function xy(x,y){return[ox+x*S,oy+(440-y)*S]}function path(points,color,width,dash=[]){ctx.beginPath();points.forEach((p,i)=>{let q=xy(p[0],p[1]);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.strokeStyle=color;ctx.lineWidth=width*S;ctx.setLineDash(dash);ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();ctx.setLineDash([])}
function label(x,y,text,size=12,color='#e7e7d4'){const q=xy(x,y);ctx.font=`600 ${size*devicePixelRatio}px system-ui`;ctx.textAlign='center';ctx.strokeStyle='#172522';ctx.lineWidth=3;ctx.strokeText(text,...q);ctx.fillStyle=color;ctx.fillText(text,...q)}
function draw(){ctx.fillStyle='#0c1719';ctx.fillRect(0,0,cv.width,cv.height);let a=xy(0,440);ctx.fillStyle='#50644c';ctx.fillRect(...a,480*S,440*S);
if(document.getElementById('terrain').checked)D.heights.forEach((row,j)=>row.forEach((z,i)=>{let q=xy(i*8,j*8+8);ctx.fillStyle=`hsl(${118-z*1.2} 16% ${26+z*.65}%)`;ctx.fillRect(...q,8*S+.5,8*S+.5)}));
path(D.creek,'#3a6470',15);path(D.creek,'#5699a6',7);
if(document.getElementById('routes').checked){Object.entries(D.paths).forEach(([n,p])=>path(p,'#b5b394',2.6,[3,3]));Object.values(D.driveways).forEach(p=>path(p,'#a5a397',3.2))}
Object.entries(D.roads).forEach(([n,r])=>{path(r.points,'#92998e',r.width+2);path(r.points,r.kind==='service'?'#6a8177':'#b6babb',r.width)});
path([[305,235],[305,291]],'#e6d4b2',7);path([[160,248],[160,282]],'#a7a88f',2.6,[3,2]);
ctx.save();let q=xy(126,220);ctx.fillStyle='#5f8258';ctx.fillRect(q[0]-19*S,q[1]-14*S,38*S,28*S);ctx.restore();label(126,229,'PARK',11);
q=xy(398,237);ctx.strokeStyle='#afba9e';ctx.lineWidth=2;ctx.strokeRect(q[0]-18*S,q[1]-16*S,36*S,32*S);label(398,248,'OLD GRAVEYARD',10);
D.buildings.forEach(b=>{let q=xy(b.x,b.y);ctx.save();ctx.translate(...q);ctx.rotate(-b.yaw*Math.PI/180);ctx.fillStyle=colors[b.category]||'#bbb';ctx.strokeStyle='#eee1bb';ctx.lineWidth=1;ctx.fillRect(-b.w*S/2,-b.d*S/2,b.w*S,b.d*S);ctx.strokeRect(-b.w*S/2,-b.d*S/2,b.w*S,b.d*S);ctx.restore();if(document.getElementById('labels').checked)label(b.x,b.y-b.d/2-4,b.id.startsWith('H')&&b.id.length===3?b.id:b.name, b.id.length===3?10:11)});
label(30,224,'WATER TOWER',10);label(55,22,'ARRIVAL',12);label(300,260,'BRIDGE',10);label(185,379,'CHURCH',12);label(364,378,'FOSTER',12);
if(document.getElementById('slice').checked)path([[55,22],[75,55],[94,87],[103,118],[109,108],[65,161],[105,194],[126,221],[208,211],[290,222],[305,235],[305,291],[305,310],[239,322],[185,344],[185,370],[177,403],[267,386],[344,371],[365,354]],'#ebbb67',.8,[6,5]);
if(document.getElementById('sight').checked)D.views.forEach(([n,a,b])=>{path([a,b],'#b7d5bd',.5,[3,5]);label(...a,'◉',14)});
let c=D.chapters.find(c=>c.chapter===+document.getElementById('chapter').value);if(c){let pts=c.path.map(id=>D.buildings.find(b=>b.id===id)).filter(Boolean);path(pts.map(b=>[b.x,b.y]),'#f4e7c0',1.8,[5,4]);pts.forEach(b=>label(b.x,b.y,'●',24,'#f3d999'))}
label(20,418,'N ↑',14);label(425,12,'100 UU = 1 m',10)}
function fit(){let r=cv.getBoundingClientRect();cv.width=r.width*devicePixelRatio;cv.height=r.height*devicePixelRatio;S=Math.min(cv.width/510,cv.height/470);ox=(cv.width-480*S)/2;oy=(cv.height-440*S)/2;draw()}function zoom(k,x=cv.width/2,y=cv.height/2){ox=x-(x-ox)*k;oy=y-(y-oy)*k;S*=k;draw()}
cv.onwheel=e=>{e.preventDefault();let r=cv.getBoundingClientRect();zoom(e.deltaY<0?1.12:1/1.12,(e.clientX-r.left)*devicePixelRatio,(e.clientY-r.top)*devicePixelRatio)};
cv.onpointerdown=e=>{drag=[e.clientX,e.clientY,ox,oy];moved=false;cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(drag){let dx=(e.clientX-drag[0])*devicePixelRatio,dy=(e.clientY-drag[1])*devicePixelRatio;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;ox=drag[2]+dx;oy=drag[3]+dy;draw()}let r=cv.getBoundingClientRect(),x=((e.clientX-r.left)*devicePixelRatio-ox)/S,y=440-((e.clientY-r.top)*devicePixelRatio-oy)/S;document.getElementById('coords').textContent=`East ${x.toFixed(1)} m · North ${y.toFixed(1)} m · Unreal (${Math.round(x*100)}, ${Math.round(y*100)})`;};
cv.onpointerup=e=>{drag=null;if(moved)return;let r=cv.getBoundingClientRect(),x=((e.clientX-r.left)*devicePixelRatio-ox)/S,y=440-((e.clientY-r.top)*devicePixelRatio-oy)/S;let b=D.buildings.find(b=>{let a=b.yaw*Math.PI/180,dx=x-b.x,dy=y-b.y;return Math.abs(dx*Math.cos(a)+dy*Math.sin(a))<b.w/2+2&&Math.abs(-dx*Math.sin(a)+dy*Math.cos(a))<b.d/2+2});if(b){side.innerHTML=`<small>CHAPTER ${b.chapter} · ${b.category.toUpperCase()}</small><h2>${b.name}</h2><dl><dt>Plan position / floor elevation</dt><dd>${b.x}, ${b.y}, ${b.z} m</dd><dt>Dimensions / wall height</dt><dd>${b.w} × ${b.d} × ${b.h} m</dd><dt>Rotation / roof rise</dt><dd>${b.yaw}° / ${b.roof} m</dd><dt>Unreal position</dt><dd>${b.unreal_position.join(', ')} UU</dd></dl><p>${b.id==='H01'?'Playable streaming door with the existing House01 interior.':b.id==='CHURCH'?'Open nave and actual service stairs connect to the basement preview.':b.id==='FOSTER'?'Exterior, wings and portico; interior remains a future chapter.':'Readable exterior blockout; interior gameplay is reserved.'}</p>`}};
D.chapters.forEach(c=>{let o=document.createElement('option');o.value=c.chapter;o.textContent=`${c.chapter}. ${c.title}`;document.getElementById('chapter').append(o)});
document.getElementById('chapter').onchange=e=>{let c=D.chapters.find(c=>c.chapter===+e.target.value);if(c)side.innerHTML=`<small>CHAPTER ${c.chapter}</small><h2>${c.title}</h2><p>${c.objective}</p><dl>${['start','encounter','optional','obstacle','unlock','exit','shortcut','implemented'].map(k=>`<dt>${k}</dt><dd>${c[k]}</dd>`).join('')}</dl><h2>Story / survival beats</h2><ol>${c.beats.map(b=>`<li>${b}</li>`).join('')}</ol>`;draw()};['terrain','labels','routes','sight','slice'].forEach(id=>document.getElementById(id).onchange=draw);document.getElementById('fit').onclick=fit;document.getElementById('plus').onclick=()=>zoom(1.3);document.getElementById('minus').onclick=()=>zoom(1/1.3);window.onresize=fit;fit();
</script></html>'''
(root/'Penance_Town_V5_Interactive.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False)))
lines=['# Penance V5 — chapter geography and expansion graph','','All fourteen regions are spatially reserved. The saved map implements a condensed opening preview; later chapter systems are planned, not production-ready.','','```mermaid','flowchart LR']
for c in p.CHAPTERS:lines.append(f' C{c["chapter"]}["{c["chapter"]}. {c["title"]}"]')
for i in range(1,14):lines.append(f' C{i} --> C{i+1}')
lines+=[' C11 -. garden shortcut .-> C10',' C12 -. return bridge .-> C6',' C14 -. changed familiar route .-> C2','```','']
for c in p.CHAPTERS:
 lines.extend([f'## {c["chapter"]}. {c["title"]}','',f'**Objective:** {c["objective"]}.',f'**Required path:** {" → ".join(c["path"])}.',f'**Survival:** {c["encounter"]}.',f'**Optional:** {", ".join(c["optional"])}.',f'**Obstacle / unlock:** {c["obstacle"]}; {c["unlock"]}.',f'**Exit / return:** {c["exit"]}; {c["shortcut"]}.','',*['- '+b for b in c['beats']],''])
(root/'Penance_V5_Chapter_Graph.md').write_text('\n'.join(lines)+'\n')
print('Published',root)
